    return this.heading('Energia e consumo','Distribuição do consumo mensal cadastrado por ativo e área.',this.exportButtons())+'<div class="metrics">'+this.metric('Consumo mensal',this.number(total),'Somatório dos ativos filtrados','bolt',true,'kWh')+this.metric('Áreas analisadas',areas.length,'Agrupamento por setor','grid')+this.metric('Ativos com consumo',assets.filter(a=>a.energyKwh>0).length,'Energia cadastrada','machine')+this.metric('Desvios por área',outliers.length,'Mais de 25% acima da média da área','pulse')+'</div>'+this.toolbar([...new Set(this.entries('assets').map(a=>a.area).filter(Boolean))].map(a=>[a,a]))+'<div class="energy-grid">'+panel('Consumo por equipamento','<div class="energy-chart">'+assets.map(a=>'<div class="energy-bar"><strong>'+this.number(a.energyKwh)+'</strong><i style="height:'+this.num(a.energyKwh)/max*85+'%"></i><span>'+e(a.tag||a.id)+'</span></div>').join('')+'</div>')+panel('Participação por área','<div class="chart-list" style="padding:0">'+areas.map(area=>{const value=assets.filter(a=>(a.area||'Sem área')===area).reduce((s,a)=>s+this.num(a.energyKwh),0),pct=total?value/total*100:0;return '<div><div class="bar-label"><span>'+e(area)+'</span><span>'+this.number(pct,1)+'%</span></div><div class="bar-track"><div class="bar-fill" style="width:'+pct+'%"></div></div></div>';}).join('')+'</div>')+'</div><div style="margin-top:24px">'+panel('Pontos de avaliação',outliers.length?outliers.map(a=>mini('<a data-swup href="'+link('ativo-detalhes',a.id)+'">'+e(a.name)+'</a>',e(a.area)+' · Compare carga, tempo de operação e capacidade antes de intervir.',this.badge('warning',this.number(a.energyKwh)+' kWh'))).join(''):'<p class="tagline">Nenhum desvio identificado na comparação disponível.</p>')+'</div><p class="tagline" style="margin-top:18px">A comparação usa a média da própria área. Equipamentos com funções diferentes podem ter consumos distintos; o indicador pede avaliação técnica.</p>';
